def escape(s: t.Any, /) -> Markup:
    """Replace the characters ``&``, ``<``, ``>``, ``'``, and ``"`` in
    the string with HTML-safe sequences. Use this if you need to display
    text that might contain such characters in HTML.

    If the object has an ``__html__`` method, it is called and the
    return value is assumed to already be safe for HTML.

    :param s: An object to be converted to a string and escaped.
    :return: A :class:`Markup` string with the escaped text.
    """
    # If the object is already a plain string, skip __html__ check and string
    # conversion. This is the most common use case.
    # Use type(s) instead of s.__class__ because a proxy object may be reporting
    # the __class__ of the proxied value.
    if type(s) is str:
        return Markup(_escape_inner(s))

    if hasattr(s, "__html__"):
        return Markup(s.__html__())

    return Markup(_escape_inner(str(s)))

it('shortcircuits preflight requests', function (done) {
  var cb = after(1, done)
  var req = new FakeRequest('OPTIONS')
  var res = new FakeResponse()

  res.on('finish', function () {
    assert.equal(res.statusCode, 204)
    cb()
  })

  cors()(req, res, function (err) {
    cb(err || new Error('should not be called'))
  })
});

it('can configure preflight success response status code', function (done) {
  var cb = after(1, done)
  var req = new FakeRequest('OPTIONS')
  var res = new FakeResponse()

  res.on('finish', function () {
    assert.equal(res.statusCode, 200)
    cb()
  })

  // act
  cors({ optionsSuccessStatus: 200 })(req, res, function (err) {
    cb(err || new Error('should not be called'))
  })
});

